<?php
$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT s.*,c.full_name customer_name,c.customer_code,srv.name service_name,th.full_name therapist_name,a.appointment_code FROM sessions s JOIN customers c ON c.id=s.customer_id JOIN services srv ON srv.id=s.service_id JOIN therapists th ON th.id=s.therapist_id LEFT JOIN appointments a ON a.id=s.appointment_id WHERE s.id=?');$q->execute([$id]);$session=$q->fetch();if(!$session){echo '<div class="alert alert-warning">Session record not found.</div>';return;}if(is_therapist()&&(int)$session['therapist_id']!==(int)(current_user()['therapist_id']??0)){http_response_code(403);echo '<div class="alert alert-danger">This session is not assigned to your account.</div>';return;}
?>
<div class="page-heading"><div><div class="eyebrow">Session record</div><h1>Session notes</h1><p><?=h($session['customer_name'])?> · <?=h($session['service_name'])?> · <?=date('F j, Y g:i A',strtotime($session['session_date']))?></p></div><a class="btn btn-outline-secondary" href="<?=h(app_page_url('appointments',['date'=>substr($session['session_date'],0,10)]))?>"><i class="bi bi-arrow-left me-1"></i>Back to schedule</a></div>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-header">Session summary</div><div class="card-body"><div class="mb-3"><div class="small-muted">Customer</div><strong><?=h($session['customer_name'])?></strong><div class="small-muted"><?=h($session['customer_code'])?></div></div><div class="mb-3"><div class="small-muted">Service performed</div><strong><?=h($session['service_name'])?></strong></div><div class="mb-3"><div class="small-muted">Therapist</div><strong><?=h($session['therapist_name'])?></strong></div><div class="mb-3"><div class="small-muted">Session date</div><?=date('F j, Y g:i A',strtotime($session['session_date']))?></div><div><div class="small-muted">Duration</div><?=h($session['duration_minutes'])?> minutes</div><?php if($session['appointment_code']):?><hr><div class="small-muted">Appointment</div><?=h($session['appointment_code'])?><?php endif;?></div></div></div><div class="col-lg-8"><div class="card"><div class="card-header">Service notes</div><div class="card-body"><?=post_form_start('save_session',app_page_url('session',['id'=>$id]))?><input type="hidden" name="id" value="<?=$id?>"><div class="alert alert-light border small"><i class="bi bi-info-circle me-1"></i>Record only information relevant to the massage/reflexology service. Avoid unnecessary sensitive medical details.</div><div class="mb-3"><label class="form-label">Customer concerns</label><textarea class="form-control" name="customer_concerns" rows="3" placeholder="Customer's stated comfort preferences or service concerns"><?=h($session['customer_concerns'])?></textarea></div><div class="mb-3"><label class="form-label">General session notes</label><textarea class="form-control" name="session_notes" rows="4" placeholder="Service delivery notes"><?=h($session['session_notes'])?></textarea></div><div class="mb-3"><label class="form-label">Recommendations</label><textarea class="form-control" name="recommendations" rows="3"><?=h($session['recommendations'])?></textarea></div><div class="mb-3"><label class="form-label">Follow-up notes</label><textarea class="form-control" name="follow_up_notes" rows="3"><?=h($session['follow_up_notes'])?></textarea></div><div class="d-flex justify-content-end"><button class="btn btn-primary"><i class="bi bi-save me-1"></i>Save session notes</button></div></form></div></div></div></div>
